model_calls.text:
[
  {
    "name": "search-flights",
    "args": {
      "cabin": {
        "anyOf": [
          {
            "enum": [
              "economy",
              "business"
            ],
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Cabin"
      },
      "date": {
        "description": "Local departure date, YYYY-MM-DD",
        "pattern": "^[0-9]{4}-10-09$",
        "title": "Date",
        "type": "string"
      },
      "destination": {
        "enum": [
          "ZRH"
        ],
        "title": "Destination",
        "type": "string"
      },
      "max_price_usd": {
        "anyOf": [
          {
            "maximum": 900,
            "minimum": 1,
            "type": "integer"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "description": "Maximum per-passenger fare, taxes included",
        "title": "Max Price Usd"
      },
      "nonstop_only": {
        "const": true,
        "default": true,
        "title": "Nonstop Only",
        "type": "boolean"
      },
      "origin": {
        "enum": [
          "BOS"
        ],
        "title": "Origin",
        "type": "string"
      },
      "passengers": {
        "default": 1,
        "description": "Number of travelers",
        "maximum": 6,
        "minimum": 1,
        "title": "Passengers",
        "type": "integer"
      }
    }
  }
]

